import {fleetShips,fleetMaxHP} from './ship-rules.js?v=2026.11.09-frontiers';
export const CANNONS=[
 ['swivel','선회포',8,82,6,1,500,4],['light','경량포',14,76,9,2,1500,5],['rapid','속사포',10,72,4,2,2500,7],['standard','표준 함포',22,70,12,3,4000,7],['long','장포',26,85,20,4,9000,10],['precision','정밀 장포',32,90,22,5,14000,12],['heavy','중포',42,58,24,6,16000,13],['large','대구경포',60,50,32,8,28000,16]
].map(([id,name,damage,accuracy,reload,weight,cost,stage])=>({id,name,damage,accuracy,reload,weight,cost,stage}));
export const QUALITIES=[['일반 I',1,0,1,1,4],['개량 II',1.2,4,.9,2.2,8],['명품 III',1.45,8,.8,4.8,12],['장인 IV',1.7,10,.72,8.5,16],['명장 V',2,12,.65,14,19]].map(([name,damage,accuracy,reload,cost,stage])=>({name,damage,accuracy,reload,cost,stage}));
export const GUN_LIMITS=[[0,0],[0,0],[0,0],[1,1],[1,2],[2,3],[2,5],[2,6],[3,8],[3,10],[3,12],[4,14],[4,18],[5,22],[5,26],[6,30],[6,34],[7,38],[7,42],[8,48]];
export function cannonStats(gun,duel=false){const c=CANNONS.find(c=>c.id===gun.kind),q=QUALITIES[gun.quality||0];if(!c||!q)throw Error('대포 종류와 품질을 확인하세요.');return {...c,name:q.name+' '+c.name,damage:Math.max(1,Math.round(c.damage*q.damage*(duel?1.5:1))),accuracy:Math.max(5,Math.min(95,c.accuracy+q.accuracy+(duel?10:0))),reload:Math.ceil((c.reload*q.reload*(duel?.7:1)-1e-10)*10)/10,cost:Math.round(c.cost*q.cost)};}
export const gunWeight=s=>(s.cannons||[]).filter(g=>g.shipId).reduce((a,g)=>a+cannonStats(g).weight,0);
export const currentHP=s=>Math.max(0,Math.min(fleetMaxHP(s),s.hullHP??fleetMaxHP(s)));
export function buyCannon(s,kind,quality=0,id=crypto.randomUUID()){if(!s.port||s.voyage)throw Error('항구에서 대포를 구입하세요.');if((s.cannons||[]).length>=100)throw Error('대포 보관 한도 100개예요.');const gun={id,kind,quality,shipId:null,readyAt:0},stats=cannonStats(gun);if(s.money<stats.cost)throw Error('대포를 구입할 두카트가 부족해요.');s.money-=stats.cost;(s.cannons??=[]).push(gun);return {ok:true,gun};}
export function equipCannon(s,id,shipId,now=Date.now()){if(!s.port||s.voyage)throw Error('항구에서 장착하세요.');const gun=s.cannons?.find(g=>g.id===id);if(!gun)throw Error('대포를 확인하세요.');if(shipId){const hull=fleetShips(s).find(p=>p.id===shipId),stats=cannonStats(gun),q=QUALITIES[gun.quality];if(!hull||hull.tier+1<Math.max(stats.stage,q.stage))throw Error('선박 단계가 낮아요.');const other=s.cannons.filter(g=>g.id!==id&&g.shipId===shipId),limits=GUN_LIMITS[hull.tier];if(other.length>=limits[0]||other.reduce((a,g)=>a+cannonStats(g).weight,0)+stats.weight>limits[1])throw Error('포대 수 또는 무게 한도를 초과해요.');}gun.shipId=shipId||null;gun.readyAt=Math.max(gun.readyAt||0,now);return {ok:true};}
export function upgradeCannon(s,id){if(!s.port||s.voyage)throw Error('항구에서 개량하세요.');const gun=s.cannons?.find(g=>g.id===id);if(!gun||gun.quality>=4)throw Error('품질을 확인하세요.');const old=cannonStats(gun),next={...gun,quality:gun.quality+1},cost=cannonStats(next).cost-old.cost;if(s.money<cost)throw Error('두카트가 부족해요.');const hull=fleetShips(s).find(p=>p.id===gun.shipId);if(hull&&hull.tier+1<QUALITIES[next.quality].stage)throw Error('장착 선박 단계가 낮아요. 먼저 장착 해제하세요.');s.money-=cost;gun.quality++;return {ok:true,cost};}
export function sellCannon(s,id){if(!s.port||s.voyage)throw Error('항구에서 매각하세요.');const gun=s.cannons?.find(g=>g.id===id);if(!gun)throw Error('대포를 확인하세요.');const total=Math.floor(cannonStats(gun).cost*.6);s.money+=total;s.cannons=s.cannons.filter(g=>g.id!==id);return {ok:true,total};}
